import os
import requests
from zipfile import ZipFile, BadZipFile
def task_func(url, download_path="mnt/data/downloads/"):
    try:
        if not isinstance(url, str) or not url.strip():
            return "Error: Unable to download the file from the provided URL."
        os.makedirs(download_path, exist_ok=True)
        response = None
        try:
            response = requests.get(url, stream=True, timeout=20)
            response.raise_for_status()
        except requests.RequestException:
            if response:
                response.close()
            return "Error: Unable to download the file from the provided URL."
        content_type = response.headers.get("Content-Type", "")
        main_type = content_type.split(";")[0].strip().lower()
        if main_type != "application/zip":
            response.close()
            return "Error: The URL does not point to a ZIP file."
        filename = None
        cd = response.headers.get("Content-Disposition", "")
        if cd:
            parts = cd.split(";")
            for p in parts:
                p = p.strip()
                if p.lower().startswith("filename="):
                    val = p.split("=", 1)[1].strip(' "')
                    filename = os.path.basename(val)
                    break
        if not filename:
            from urllib.parse import urlparse, unquote
            parsed = urlparse(url)
            base = os.path.basename(parsed.path)
            filename = unquote(base) if base else "downloaded.zip"
        if not filename.lower().endswith(".zip"):
            filename += ".zip"
        file_path = os.path.join(download_path, filename)
        with open(file_path, "wb") as f:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)
        response.close()
        try:
            with ZipFile(file_path) as zf:
                zf.extractall(download_path)
        except BadZipFile:
            return "Error: The downloaded file is not a valid ZIP file."
        return download_path
    except Exception as e:
        return f"Error: {e}"

