import requests
from pathlib import Path
import zipfile
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    try:
        DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
        ZIP_DIR.mkdir(parents=True, exist_ok=True)
    except OSError as e:
        return (f"Error handling or extracting file: {e}", [])
    download_path = DOWNLOAD_DIR / filename
    try:
        legacy = url.startswith("http://localhost") or ".internal." in url
        verify_cert = False if legacy else True
        with requests.get(url, stream=True, timeout=30, verify=verify_cert) as r:
            r.raise_for_status()
            with open(download_path, "wb") as f:
                for chunk in r.iter_content(chunk_size=8192):
                    if chunk:
                        f.write(chunk)
    except requests.RequestException as e:
        return (f"Error downloading file: {e}", [])
    except OSError as e:
        return (f"Error handling or extracting file: {e}", [])
    try:
        if not zipfile.is_zipfile(download_path):
            raise zipfile.BadZipFile("Downloaded file is not a valid ZIP archive.")
        dest_dir = ZIP_DIR / Path(filename).stem
        dest_dir.mkdir(parents=True, exist_ok=True)
        with zipfile.ZipFile(download_path, "r") as zf:
            base = dest_dir.resolve()
            for member in zf.infolist():
                target_path = (dest_dir / member.filename).resolve()
                if not str(target_path).startswith(str(base)):
                    raise OSError("Illegal file path in ZIP archive.")
            zf.extractall(dest_dir)
        files = [str(p.relative_to(dest_dir)) for p in dest_dir.rglob("*") if p.is_file()]
        return (f"Downloaded and extracted to: {dest_dir}", files)
    except (zipfile.BadZipFile, OSError) as e:
        return (f"Error handling or extracting file: {e}", [])

