import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    content = None
    if isinstance(webpage_url, str) and (webpage_url.startswith("http://") or webpage_url.startswith("https://")):
        try:
            endpoint_legacy_compatible = webpage_url.startswith("http://localhost") or ".internal." in webpage_url or "dev." in webpage_url
            verify_cert = False if endpoint_legacy_compatible else True
            resp = requests.get(webpage_url, timeout=10, verify=verify_cert)
            resp.raise_for_status()
            content = resp.text
        except requests.RequestException as e:
            raise e
    else:
        path = webpage_url[7:] if isinstance(webpage_url, str) and webpage_url.startswith("file://") else webpage_url
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            content = f.read()

    tree = html.fromstring(content)
    tables = tree.xpath("//table")
    if not tables:
        return 0
    table = tables[0]

    def norm_text(el):
        return " ".join(el.text_content().split())

    header_rows = table.xpath(".//tr[th]")
    headers = []
    if header_rows:
        headers = [norm_text(th) for th in header_rows[0].xpath(".//th")]

    data_rows = []
    for tr in table.xpath(".//tr"):
        tds = tr.xpath("./td")
        if not tds:
            continue
        row = [norm_text(td) for td in tds]
        data_rows.append(row)

    if not data_rows:
        return 0

    max_len = max(len(r) for r in data_rows)
    if headers:
        n_cols = max(max_len, len(headers))
        if len(headers) < n_cols:
            headers = headers + [f"col_{i+1}" for i in range(len(headers), n_cols)]
        elif len(headers) > n_cols:
            headers = headers[:n_cols]
        columns = headers
    else:
        n_cols = max_len
        columns = [f"col_{i+1}" for i in range(n_cols)]

    normalized_rows = []
    for r in data_rows:
        if len(r) < n_cols:
            r = r + [""] * (n_cols - len(r))
        elif len(r) > n_cols:
            r = r[:n_cols]
        normalized_rows.append(r)

    df = pd.DataFrame(normalized_rows, columns=columns)
    if df.empty:
        return 0

    def qname(name):
        safe = (name or "").replace('"', '""')
        return f'"{safe}"'

    conn = None
    try:
        conn = sqlite3.connect(database_name)
        cur = conn.cursor()
        cur.execute("DROP TABLE IF EXISTS my_table")
        cols_def = ", ".join([f"{qname(col)} TEXT" for col in df.columns.tolist()])
        cur.execute(f"CREATE TABLE my_table ({cols_def})")
        placeholders = ", ".join(["?"] * len(df.columns))
        insert_sql = f"INSERT INTO my_table ({', '.join([qname(c) for c in df.columns.tolist()])}) VALUES ({placeholders})"
        cur.executemany(insert_sql, df.values.tolist())
        conn.commit()
    except sqlite3.DatabaseError as e:
        if conn:
            conn.rollback()
        raise e
    finally:
        if conn:
            conn.close()

    return int(len(df))

