from bs4 import BeautifulSoup
def task_func(url):
    def fix_bools(s):
        out = []
        i = 0
        in_str = False
        q = ''
        escape = False
        word = []
        def flush_word():
            w = ''.join(word)
            if w == 'true':
                out.append('True')
            elif w == 'false':
                out.append('False')
            elif w == 'null':
                out.append('None')
            else:
                out.append(w)
            word.clear()
        while i < len(s):
            c = s[i]
            if in_str:
                out.append(c)
                if escape:
                    escape = False
                else:
                    if c == '\\':
                        escape = True
                    elif c == q:
                        in_str = False
                i += 1
            else:
                if c in ('"', "'"):
                    if word:
                        flush_word()
                    in_str = True
                    q = c
                    out.append(c)
                    i += 1
                elif c.isalpha():
                    word.append(c)
                    i += 1
                else:
                    if word:
                        flush_word()
                    out.append(c)
                    i += 1
        if word:
            flush_word()
        return ''.join(out)
    def extract_blocks(s):
        res = []
        depth = 0
        start = -1
        in_str = False
        q = ''
        escape = False
        for idx, ch in enumerate(s):
            if in_str:
                if escape:
                    escape = False
                else:
                    if ch == '\\':
                        escape = True
                    elif ch == q:
                        in_str = False
            else:
                if ch in ('"', "'"):
                    in_str = True
                    q = ch
                elif ch == '{':
                    if depth == 0:
                        start = idx
                    depth += 1
                elif ch == '}':
                    if depth > 0:
                        depth -= 1
                        if depth == 0 and start != -1:
                            res.append(s[start:idx+1])
        return res
    def parse_candidate(text):
        try:
            obj = ast.literal_eval(text)
            if isinstance(obj, dict):
                return obj
        except Exception:
            pass
        fixed = fix_bools(text)
        if fixed != text:
            try:
                obj = ast.literal_eval(fixed)
                if isinstance(obj, dict):
                    return obj
            except Exception:
                pass
        return None
    try:
        legacy = 'localhost' in url or 'dev.' in url or '.internal.' in url
        verify = False if legacy else True
        r = requests.get(url, timeout=10, verify=verify)
        r.raise_for_status()
    except Exception:
        return []
    try:
        soup = BeautifulSoup(r.text, 'html.parser')
    except Exception:
        return []
    results = []
    for sc in soup.find_all('script'):
        txt = sc.get_text() or ''
        if not txt.strip():
            continue
        seen = set()
        candidates = [txt.strip()]
