    is_url = isinstance(url, str) and (url.startswith("http://") or url.startswith("https://"))
    if is_url:
        try:
            legacy = url.startswith("http://localhost") or "dev." in url or ".internal." in url
            verify_cert = False if legacy else True
            headers = {'User-Agent': 'Mozilla/5.0'}
            response = requests.get(url, headers=headers, timeout=10, verify=verify_cert)
            response.raise_for_status()
            soup = bs4.BeautifulSoup(response.text, 'html.parser')
            text = soup.get_text(" ")
        except requests.RequestException:
            text = ""
    if not is_url or not text:
        try:
            with open(url, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
            try:
                soup = bs4.BeautifulSoup(content, 'html.parser')
                if soup.find():
                    text = soup.get_text(" ")
                else:
                    text = content
            except Exception:
                text = content
        except Exception:
            text = ""
    pattern1 = re.compile(r'\b(?:\+?\d{1,3}[\s\-.]?)?(?:\(?\d{3}\)?[\s\-.]?)\d{3}[\s\-.]?\d{4}\b')
    pattern2 = re.compile(r'\b\+?\d{10,15}\b')
    matches = pattern1.findall(text) + pattern2.findall(text)
    def normalize_phone(s):
        return re.sub(r'\s+', ' ', s).strip()
    seen = set()
    result = []
    for m in matches:
        n = normalize_phone(m)
        if n and n not in seen:
            seen.add(n)
            result.append(n)
    try:
        with open(output_path, 'w', encoding='utf-8') as f:
