import re
import json
import requests
def task_func(data_url: str) -> list:
    try:
        response = requests.get(data_url, timeout=10)
        text = response.text
    except Exception:
        return "Invalid url input"

    ranges = []
    in_string = False
    escape = False
    array_depth = 0
    range_start = None
    for i, ch in enumerate(text):
        if in_string:
            if escape:
                escape = False
            elif ch == '\\':
                escape = True
            elif ch == '"':
                in_string = False
            continue
        else:
            if ch == '"':
                in_string = True
                continue
            if ch == '[':
                if array_depth == 0:
                    range_start = i
                array_depth += 1
                continue
            if ch == ']':
                if array_depth > 0:
                    array_depth -= 1
                    if array_depth == 0 and range_start is not None:
                        ranges.append((range_start, i))
                        range_start = None
                continue

    def inside_ranges(pos):
        for a, b in ranges:
            if a <= pos <= b:
                return True
        return False

    pattern = re.compile(r'"\s*name\s*"\s*:\s*"([^"]+)"', re.IGNORECASE)
    names = []
    for m in pattern.finditer(text):
        if not inside_ranges(m.start()):
            names.append(m.group(1))
    return names

