        stack = [data]
        strings = []
        while stack:
            v = stack.pop()
            if isinstance(v, dict):
                stack.extend(v.values())
            elif isinstance(v, list):
                stack.extend(v)
            elif isinstance(v, str):
                strings.append(v)
        extracted_text = " ".join(strings)
    except Exception:
        extracted_text = text
    cleaned = re.sub(r"\[[^\]]*\]", " ", extracted_text)
    pattern = r"\b[A-Z][a-z]+(?:\s[A-Z][a-z]+)*\b"
    names = re.findall(pattern, cleaned)
    return names

