    response = requests.get(url, verify=verify_cert)
    response.raise_for_status()
    df = pd.read_csv(StringIO(response.text))
    if isinstance(sort_by_column, (list, tuple)):
        sort_cols = list(sort_by_column)
    else:
        sort_cols = [sort_by_column]
    for c in sort_cols:
        if c not in df.columns:
            raise ValueError(f"Column '{c}' not found in DataFrame.")
    if len(sort_cols) == 1:
        secondary = None
        for candidate in ["title", "id"]:
            if candidate in df.columns and candidate not in sort_cols:
                secondary = candidate
                break
        if secondary is None:
            for candidate in df.columns:
                if candidate not in sort_cols:
                    secondary = candidate
                    break
        if secondary:
            sort_cols.append(secondary)
    sorted_df = df.sort_values(by=sort_cols)
    return sorted_df

